492:   const stageCounts: Record<string, number> = {};
493:   for (const s of Object.values(altitudes)) {
494:     stageCounts[s] = (stageCounts[s] ?? 0) + 1;
495:   }
496:   let dominantStage: Stage = 'Red';
497:   let maxCount = 0;
498:   for (const [s, count] of Object.entries(stageCounts)) {
499:     if (count > maxCount || (count === maxCount && CAL_STAGES.indexOf(s as typeof CAL_STAGES[number]) > CAL_STAGES.indexOf(dominantStage))) {
500:       maxCount = count;
501:       dominantStage = s as Stage;
502:     }
503:   }
504: 
505:   return createSignificator('cli-player', altitudes, dominantStage);
506: }
