724: // ── AgenticOrchestrator encounter handler (all modalities) ────────────
725: async function runAgenticEncounter(
726:   encounter: ScheduledEncounter,
727:   sig: Significator,
728:   world: WorldState,
729:   history: ConsequenceRecord[],
730:   responsesPool?: number[],
731:   consecutivePasses?: Map<string, number>,
732: ): Promise<{
733:   outcome: import('../src/core/assessments/AgenticOrchestrator.js').OrchestratorResult;
734:   response: PlayerResponse;
735:   narrativeSummary: string;
736: }> {
737:   const [encLine, encStage] = encounter.moduleRef.split(':') as [Line, Stage];
738:   const modRegistry = (globalThis as any).__moduleRegistry as ModuleRegistry | undefined;
739: 
740:   // If --line/--stage/--modality forcing is active, override the encounter
741:   let forcedEncounter = encounter;
742:   if (FORCE_LINE || FORCE_STAGE || FORCE_MODALITY) {
743:     const forcedLine = FORCE_LINE ?? encLine;
744:     const forcedStage = FORCE_STAGE ?? encStage;
745:     const forcedModality = FORCE_MODALITY ?? encounter.modality;
746:     const forcedModule = modRegistry?.get(forcedLine, forcedStage);
747:     if (forcedModule) {
748:       forcedEncounter = {
749:         ...encounter,
750:         moduleRef: `${forcedLine}:${forcedStage}`,
751:         modality: forcedModality,
752:         targetLines: [forcedLine],
753:         stage: forcedStage,
754:       };
755:     }
756:   }
757: 
758:   const uiHandler: AgenticUIHandler = {
759:     askUser: async (params: AskUserQuestionParams): Promise<AskUserQuestionResult> => {
760:       const answers: UserAnswer[] = [];
761: 
762:       for (const q of params.questions) {
763:         if (!JSON_MODE) {
764:           const mod = forcedEncounter.modality;
765:           const isShadow = forcedEncounter.executionMode === 'shadow';
766:           let modHeader = '';
767: 
768:           switch (mod) {
769:             case 'Deterministic':
770:               modHeader = isShadow
771:                 ? `${chalk.bold.red('◆ [SHADOW TRIAL] ▬▬▬▬▬▬▬▬▬▬▬▬▬░ (9.5s remaining)')}\n`
772:                 : `${chalk.bold.red('⏳ [TIMED TRIAL] ▬▬▬▬▬▬▬▬▬▬▬▬▬░ (9.5s remaining)')}\n`;
773:               break;
774:             case 'LanguageReflective':
775:               modHeader = isShadow
776:                 ? `${chalk.bold.red('◆ [SHADOW REFLECTION] • Confront the unresolved pattern •')}\n`
777:                 : `${chalk.bold.blue('🧘 [REFLECTION BEAT] • Tune in to your inner state •')}\n`;
778:               break;
779:             case 'ScenarioChoice':
780:               modHeader = isShadow
781:                 ? `${chalk.bold.red('◆ [SHADOW CROSSROADS] • The shadow demands a choice •')}\n`
782:                 : `${chalk.bold.yellow('🔀 [DECISION CROSSROADS] • A path diverges •')}\n`;
783:               break;
784:             case 'Embodied':
785:               modHeader = isShadow
786:                 ? `${chalk.bold.red('◆ [SHADOW SCAN] • Feel where the shadow lives in the body •')}\n`
787:                 : `${chalk.bold.green('💓 [SOMATIC SCAN] • Focus on body sensation •')}\n`;
788:               break;
789:             case 'Strategic':
790:               modHeader = isShadow
791:                 ? `${chalk.bold.red('◆ [SHADOW WAR-TABLE] • Map the shadow\'s strategy •')}\n`
792:                 : `${chalk.bold.magenta('♟️ [TACTICAL WAR-TABLE] • Assess constraints •')}\n`;
793:               break;
794:             case 'SocialCooperative':
795:               modHeader = isShadow
796:                 ? `${chalk.bold.red('◆ [SHADOW DIPLOMACY] • Navigate the shadow in relation •')}\n`
797:                 : `${chalk.bold.cyan('🤝 [DIPLOMACY] • Navigating connection •')}\n`;
798:               break;
799:             case 'ImmersiveRPG':
800:               modHeader = isShadow
801:                 ? `${chalk.bold.red('◆ [SHADOW SCENE] • The shadow writes its chapter •')}\n`
802:                 : `${chalk.bold.yellow('📖 [NARRATIVE SCENE] • The story unfolds •')}\n`;
803:               break;
804:             default:
805:               modHeader = isShadow
806:                 ? `${chalk.bold.red('◆ [SHADOW WORK]')}\n`
807:                 : `${chalk.bold.dim('[' + (mod as string).toUpperCase() + ']')}\n`;
808:           }
809: 
810:           console.log(`\n  ${modHeader}  ${chalk.magenta('[' + q.header + ']')}`);
811:           console.log(`  ${chalk.bold(q.question)}`);
812:           if (q.options?.length) {
813:             for (let i = 0; i < q.options.length; i++) {
814:               const opt = q.options[i];
815:               console.log(`    ${chalk.cyan('[' + (i + 1) + ']')} ${opt.label} — ${opt.description}`);
816:             }
817:           }
818:         }
819: 
820:         emitEvent('ask_user', {
821:           header: q.header,
822:           question: q.question,
823:           options: q.options?.map((o, i) => ({ index: i + 1, label: o.label, description: o.description })),
824:           allowWriteIn: q.allowWriteIn,
825:         });
826: 
827:         if (HEADLESS) {
828:           // Use forced responses pool if provided (one index per question, consumed sequentially)
829:           let selectedIdx: number;
830:           if (responsesPool && responsesPool.length > 0) {
831:             const forcedIdx = responsesPool.shift()!;
832:             if (q.options && forcedIdx >= 1 && forcedIdx <= q.options.length) {
833:               selectedIdx = forcedIdx - 1;
834:             } else {
835:               selectedIdx = 0;
836:             }
837:           } else {
838:             // Vary selection to probe different shadow patterns:
839:             // Cycle through options to ensure shadow detection has varied input
840:             const hash = (Date.now() + (q.options?.length ?? 4)) % 4;
841:             selectedIdx = hash < (q.options?.length ?? 4) ? hash : 0;
842:           }
843:           const selectedOpt = q.options?.[selectedIdx];
844:           const selectedLabel = selectedOpt?.label ?? '';
845: 
846:           // Shadow keyword injection for testing — randomly inject (10% chance)
847:           // to allow MOST encounters to pass and demonstrate altitude shifts.
848:           // When FORCE_SHADOW=none, skip injection entirely for clean progression.
849:           const shadowInjections = ['', 'i feel the need to withdraw from this confrontation', 'i must transcend these petty concerns and reach enlightenment', 'i prefer to stay here where it is safe and comfortable'];
850:           const injectShadow = FORCE_SHADOW !== 'none' && selectedIdx > 0 && Math.random() < 0.1;
851:           const writeInShadow = injectShadow ? (shadowInjections[selectedIdx] ?? '') : '';
852: 
853:           if (writeInShadow) {
854:             answers.push({ selectedLabels: [selectedLabel], writeInValue: writeInShadow });
855:           } else {
856:             answers.push({ selectedLabels: [selectedLabel] });
857:           }
858:         } else {
859:           const promptText = q.multiSelect
860:             ? '\n  Select (comma-separated): '
861:             : '\n  Select: ';
862:           const answer = await ask(promptText);
863:           const selections = answer.split(',').map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n));
864:           const selectedLabels = selections
865:             .filter(n => n >= 1 && n <= (q.options?.length ?? 0))
866:             .map(n => q.options![n - 1]!.label);
867: 
868:           // Determine if input is a simple numeric choice from the options
869:           let isSimpleNumericChoice = false;
870:           if (q.options?.length && answer.trim()) {
871:             const parts = answer.split(',').map(s => s.trim());
872:             isSimpleNumericChoice = parts.every(part => {
873:               const num = parseInt(part, 10);
874:               return !isNaN(num) && String(num) === part && num >= 1 && num <= q.options!.length;
875:             });
876:           }
877: 
878:           if (q.allowWriteIn || (!q.options?.length && answer.trim())) {
879:             // Only populate writeInValue if it's NOT a simple numeric choice
880:             if (!isSimpleNumericChoice && answer.trim()) {
881:               answers.push({ selectedLabels, writeInValue: answer.trim() });
882:             } else {
883:               answers.push({ selectedLabels });
884:             }
885:           } else {
886:             answers.push({ selectedLabels });
887:           }
888:         }
889:       }
890: 
891:       return { answers };
892:     }
893:   };
894: 
895:   // Always route through AgenticOrchestrator — it handles LLM + fallback internally
896:   // Look up the assessment module from the registry to inject into the LLM context
897:   const baseModule = modRegistry?.get(encLine, encStage);
898: 
899:   // Build ConceptDraftIndex from the module registry so the LLM sees module metadata
900:   const conceptModules: Record<string, any> = {};
901:   if (modRegistry) {
902:     for (const m of modRegistry.getAll()) {
903:       const key = `${m.line.toLowerCase()}:${m.stage.toLowerCase()}`;
904:       conceptModules[key] = {
905:         line: m.line,
906:         stage: m.stage,
907:         title: `${m.line} ${m.stage} Module`,
908:         modalities: m.tasks.map(t => t.type === 'llm_dialogue' ? 'LanguageReflective' as const : 'Deterministic' as const),
909:       };
910:     }
911:   }
912: 
913:   const orchestrator = new AgenticOrchestrator({
914:     encounter: forcedEncounter,
915:     significator: sig,
916:     world,
917:     history,
918:     conceptIndex: { modules: conceptModules },
919:     uiHandler,
920:     module: modRegistry?.get(FORCE_LINE ?? encLine, FORCE_STAGE ?? encStage) ?? baseModule,
921:     noLlm: !LLM_ACTIVE,
922:     forceShadow: FORCE_SHADOW,
923:     consecutivePasses,
924:   });
925: 
926:   const outcome = await orchestrator.run();
927: 
928:   // Build a PlayerResponse from the orchestrator's consequence record
929:   const cr = outcome.consequenceRecord;
930:   const response: PlayerResponse = {
931:     encounterId: encounter.id,
932:     energeticDirection: cr.polarityTrace.energeticDirection,
933:     driveDirectionality: cr.polarityTrace.driveDirectionality,
934:     stageOrientation: cr.polarityTrace.stageOrientation,
935:     sourceOfNourishment: cr.polarityTrace.sourceOfNourishment,
936:     shadowSurfaced: cr.shadowSurfaced,
937:     shadowResolvedId: cr.shadowResolved,
938:     narrativeSummary: outcome.narrativeSummary,
939:   };
940: 
941:   return { outcome, response, narrativeSummary: outcome.narrativeSummary };
942: }
